#[test]
fn actual_partition_replacement_inverse_freezes_unrelated_ieee_and_ordered_raw_owners() {
    use super::super::apply_vt_conformance_mutation;
    use crate::standards::v1_7::subsets::base::schema::snapshot::{PdfPage, PdfDecimal, PdfDictEntry};
    use semio_framework_value::ToValue;
    let words = [0u64, 0x8000000000000000, 0x7ff0000000000000, 0xfff0000000000000, 0x7ff8000000000042, 0x7ff0000000000001, 1, 0x7fefffffffffffff];
    for word in words {
    let mut base = PdfSnapshot::default();
    let catalog = support::insert_object(&mut base, support::dict(vec![("Type", PdfObject::Name("Catalog".into()))]));
        base.trailer.push(crate::standards::v1_7::subsets::base::schema::snapshot::PdfDictEntry::new("Root", PdfObject::Ref(catalog)));
    let pages = support::insert_object(&mut base, support::dict(vec![("Type", PdfObject::Name("Pages".into())), ("Count", PdfObject::Int(1))]));
    let page = support::insert_object(&mut base, support::dict(vec![("Type", PdfObject::Name("Page".into())), ("Parent", PdfObject::Ref(pages)), ("MediaBox", PdfObject::numbers(&[0.0, 0.0, 100.0, 100.0]))]));
    support::set_entry(&mut base, catalog, "Pages", PdfObject::Ref(pages));
    support::set_entry(&mut base, pages, "Kids", PdfObject::Array(vec![PdfObject::Ref(page)]));
    base.pages.push(PdfPage::new(100.0, 100.0));
        base.schema = "neutral-custom-frozen-owner".into();
        base.pages[0].duration = Some(f64::from_bits(word));
        let extra = support::insert_object(&mut base, PdfObject::Dict(vec![PdfDictEntry::new("Repeated", PdfObject::Real(PdfDecimal { negative: true, coefficient: "0".into(), scale: 0 })), PdfDictEntry::new("Repeated", PdfObject::Str(vec![0, 255, 13, 10]))]));
        assert!(support::object(&base, extra).is_some());
        support::set_dpart_root(&mut base, "old retained Job");
        let original = store::pack_rt::encode_wire_value(&base.to_value());
        let mutation = SetDpartRoot { job: "new retained Job".into() };
        let inverse = <SetDpartRoot as MutationKind<PdfSnapshot, PdfVtMutation>>::inverse(&mutation, &base).unwrap();
        let mut next = base.clone();
        assert!(apply_vt_conformance_mutation(&mut next, &PdfVtMutation::SetDpartRoot(mutation)).messages().is_empty());
        assert_eq!(next.schema, base.schema);
        assert_eq!(next.pages[0].duration.unwrap().to_bits(), word);
        assert_eq!(support::dpart_job(&next).as_deref(), Some("new retained Job"));
        for undo in inverse { assert!(apply_vt_conformance_mutation(&mut next, &undo).messages().is_empty()); }
        assert_eq!(store::pack_rt::encode_wire_value(&next.to_value()), original, "complete ordered owner and every raw IEEE word must restore exactly");
    }
}
